-- 검사를 다듬는다

@Component
class PointcutAudit implements InitializingBean {

    @Override
    public void afterPropertiesSet() {
        for (Method m : Pointcuts.class.getDeclaredMethods()) {
            Pointcut pc = m.getAnnotation(Pointcut.class);
            if (pc == null) continue;
            AspectJExpressionPointcut p = new AspectJExpressionPointcut();
            p.setExpression("study.adv.aspect.Pointcuts." + m.getName() + "()");
            long n = count(p);
            log.info("[검사] {} 맞는 메서드 {}", m.getName(), n);
            if (n == 0) throw new IllegalStateException("0 개 매칭: " + m.getName());
        }
    }
}

